import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"1.2 Build the complete experience prototype","description":"Walk through tasks, approval, artifacts, and recovery in a clickable prototype.","frontmatter":{"title":"1.2 Build the complete experience prototype","description":"Walk through tasks, approval, artifacts, and recovery in a clickable prototype.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-1/1-2.md","filePath":"en/delivery/stage-1/1-2.md","lastUpdated":1794015952000}'),l={name:"en/delivery/stage-1/1-2.md"};function i(n,e,s,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1-2-build-the-complete-experience-prototype" tabindex="-1">1.2 Build the complete experience prototype <a class="header-anchor" href="#_1-2-build-the-complete-experience-prototype" aria-label="Permalink to &quot;1.2 Build the complete experience prototype&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Done:</strong> The real web control surface walks through task cards, approval, artifacts, and failure recovery across queued, running, awaiting-approval, complete, failed, and recoverable states.</li><li><strong>Boundary:</strong> The prototype does not fake success; unknown, failed, and incomplete states are shown honestly.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Build a clickable prototype that covers the full user path so the product can be understood before real development starts. The prototype must include task cards, approval, artifacts, and failure recovery, not just a home page.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Design four main entries: today, needs you, artifacts, and settings.</li><li>Cover every important task state: queued, running, waiting for information, waiting for approval, completed, failed, recoverable, and cancelled.</li><li>Keep one primary action per state and state clearly what the user should do next.</li><li>Make task cards, approval pages, artifact pages, and failure explanations click through as one complete flow.</li><li>Use sample data, but never fake success; show unknown, failed, and incomplete states honestly.</li><li>Ask the first user to walk through it on desktop and phone, then fix the confusing parts.</li></ol>',7)])])}const f=t(l,[["render",i]]);export{h as __pageData,f as default};
